    if (this != &other) {
      minlc = std::move(other.minlc); maxlc = std::move(other.maxlc);
      Xmax = other.Xmax; Xmin = other.Xmin; Ymax = other.Ymax; Ymin = other.Ymin;
      count_ = other.count_;
      min_hint_ = other.min_hint_; max_hint_ = other.max_hint_;
