  }
#if (defined(__clang__) || defined(__GNUC__))
  [[gnu::always_inline]]
#endif
  void add(ld x, ld y) {
    check_coefficients(x, y);
#if defined(__clang__) && defined(SKIP_RUNTIME_CHECKS)
    if (count_ == std::numeric_limits<std::size_t>::max()) [[unlikely]] count_error();
#else
