struct P { std::int64_t x,y; };
struct Q { std::int64_t a,b; };
static void barrier() { std::atomic_signal_fence(std::memory_order_seq_cst); }
using Clock=std::chrono::steady_clock;
template<int mode> [[gnu::noinline]] static std::uint64_t query(const LineContainer2D& h,const std::vector<Q>& qs) {
    std::uint64_t sum=0;barrier();
    for (const auto q:qs) {
        std::int64_t value{};
        if constexpr(mode==0)value=h.min_rounded_ll(q.a,1);
        if constexpr(mode==1)value=h.max_rounded_ll(q.a,1);
        if constexpr(mode==2)value=std::llround(h.min_ld(q.a,q.b));
        if constexpr(mode==3)value=std::llround(h.min_ld(static_cast<long double>(q.a)/4,static_cast<long double>(q.b)/8));
        if constexpr(mode==4)value=h.min_rounded_ll(0,q.b);
        sum+=static_cast<std::uint64_t>(value);
    }
    barrier();return sum;
}
template<int mode> static void measure(const char* shape,const char* name,const LineContainer2D& h,const std::vector<Q>& qs) {
    const auto t=Clock::now();auto sum=query<mode>(h,qs);const auto elapsed=std::chrono::duration<double,std::nano>(Clock::now()-t).count()/qs.size();
    std::printf("%s:%s %.9f %llu\n",shape,name,elapsed,static_cast<unsigned long long>(sum));
}
int main() {
    for (const auto shape: {"one","two","tiny","random","parabola","duplicates"}) {
        const std::string s=shape;const int n=s=="one"?1:s=="two"?2:s=="tiny"?32:s=="parabola"?20000:50000;
        std::mt19937_64 random(982157);std::vector<P> points;points.reserve(n);
        for(int i=0;i<n;++i) {
            if(s=="parabola") { std::int64_t x=i-n/2;points.push_back({x,x*x}); }
            else if(s=="duplicates")points.push_back({31,-29});
            else points.push_back({std::int64_t(random()%2000000001)-1000000000,std::int64_t(random()%2000000001)-1000000000});
        }
        std::vector<Q> qs(200000);for(auto& q:qs)q={std::int64_t(random()%2000000001)-1000000000,std::int64_t(random()%2000000001)-1000000000};
        const int repetitions=n<=32?1000:3;double ns=0;std::uint64_t count=0;
        for(int rep=0;rep<repetitions;++rep) {const auto begin=Clock::now();LineContainer2D h;for(auto v:points)h.add(v.x,v.y);barrier();ns+=std::chrono::duration<double,std::nano>(Clock::now()-begin).count();count+=h.size();}
        std::printf("%s:build %.9f %llu\n",shape,ns/repetitions,static_cast<unsigned long long>(count));
        LineContainer2D h;for(auto v:points)h.add(v.x,v.y);
        measure<0>(shape,"minline",h,qs);measure<1>(shape,"maxline",h,qs);measure<2>(shape,"integer2d",h,qs);measure<3>(shape,"float2d",h,qs);measure<4>(shape,"axis",h,qs);
    }
}

