from pathlib import Path
p=Path(__file__).parent;s=(p/'baseline.hpp').read_text();needle='''  static ld nonzero_value(const Hull& hull, const Hint& hint, ld a, ld b) {
'''
body='''    if constexpr (proof && cache_points) {
      if (hint.small == 1) {
        const auto& line = hint.positive.cached;
        const ld result = a * line.m + b * line.k;
        if (std::isnan(result)) [[unlikely]] return recover_line_dot(a, b, &line);
        return result;
      }
      if (hint.small == 2 || hint.small >= 4) {
        const auto& left = hint.positive.cached;
        const auto& right = hint.negative.cached;
        ld x = a * left.m + b * left.k;
        ld y = a * right.m + b * right.k;
        if (std::isnan(x)) [[unlikely]] x = recover_line_dot(a, b, &left);
        if (std::isnan(y)) [[unlikely]] y = recover_line_dot(a, b, &right);
        if constexpr (std::is_same_v<Hull, MaxLineContainer<ld>> != negative_a)
          return std::max(x, y);
        else return std::min(x, y);
      }
    }
'''
assert s.count(needle)==1;(p/'twopoint.hpp').write_text(s.replace(needle,needle+body))
s=(p/'direct.hpp').read_text();(p/'direct_two.hpp').write_text(s.replace(needle,needle+body))

