from pathlib import Path
p=Path(__file__).parent
marker='''  static ll to_rounded_integer(ld value) {
'''
body='''#if (defined(__GNUC__) || defined(__clang__)) && (defined(__i386__) || defined(__x86_64__)) && !defined(SIRKIT_DISABLE_SIMD)
  [[gnu::target("sse3"), gnu::noinline]]
  static ll sse3_rounded_integer(ld value) {
    const ld limited = std::clamp(value, -INF, INF);
    const ll integral = static_cast<ll>(limited);
    const ld fraction = limited - ld(integral);
    return integral + (fraction >= 0.5L) - (fraction <= -0.5L);
  }
  static bool has_sse3() {
    static const bool supported = [] { __builtin_cpu_init(); return __builtin_cpu_supports("sse3") != 0; }();
    return supported;
  }
#endif
'''
route='''#if (defined(__GNUC__) || defined(__clang__)) && (defined(__i386__) || defined(__x86_64__)) && !defined(SIRKIT_DISABLE_SIMD)
    if constexpr (std::numeric_limits<ld>::digits == 64)
      if (has_sse3()) return sse3_rounded_integer(value);
#endif
'''
for v,name in [('baseline','sse3'),('direct','direct_sse3')]:
 s=(p/(v+'.hpp')).read_text();assert s.count(marker)==1;(p/(name+'.hpp')).write_text(s.replace(marker,body+marker+route))
o=p/'sse3';o.mkdir(exist_ok=True)
for v in ['baseline','control','direct','sse3','direct_sse3']:(o/(v+'.hpp')).write_bytes((p/(v+'.hpp')).read_bytes())
