opt/make_abi.py.source:
from pathlib import Path
p=Path(__file__).parent
marker='''  static ll to_rounded_integer(ld value) {
    const ld limited = std::clamp(value, -INF, INF);
'''
body='''#if defined(__linux__) && defined(__x86_64__) && (defined(__GNUC__) || defined(__clang__)) && \\
    !defined(SIRKIT_LINE_CONTAINER_FORCE_PORTABLE) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    if constexpr (sizeof(ld) == 16 && std::numeric_limits<ld>::digits == 64 &&
                  std::numeric_limits<ld>::max_exponent == 16384 &&
                  std::numeric_limits<ld>::radix == 2 && std::endian::native == std::endian::little) {
      std::array<std::byte, 10> bytes;
      std::memcpy(bytes.data(), &limited, bytes.size());
      std::uint64_t significand;
      std::uint16_t sign_exponent;
      std::memcpy(&significand, bytes.data(), sizeof(significand));
      std::memcpy(&sign_exponent, bytes.data() + sizeof(significand), sizeof(sign_exponent));
      const unsigned exponent = sign_exponent & 0x7fffU;
      if (exponent < 16382U) return 0;
      if (exponent > 16444U)
        throw std::overflow_error("LineContainer2D: invalid rounded value");
      const std::uint64_t magnitude = exponent == 16382U ? std::uint64_t{1} :
          (significand >> (16446U - exponent)) + ((significand >> (16445U - exponent)) & std::uint64_t{1});
      const ll result = static_cast<ll>(magnitude);
      return sign_exponent & 0x8000U ? -result : result;
    }
#endif
'''
for v,name in [('baseline','abi'),('direct','direct_abi')]:
 s=(p/(v+'.hpp')).read_text();assert s.count(marker)==1
 s=s.replace('#include <algorithm>','#include <algorithm>\n#include <array>\n#include <bit>\n#include <cstring>',1)
 s=s.replace(marker,marker+body);(p/(name+'.hpp')).write_text(s)
 public=s.replace('  static ll to_rounded_integer(ld value) {',' public:\n  static ll test_round(ld value) { return to_rounded_integer(value); }\n private:\n  static ll to_rounded_integer(ld value) {',1);(p/(name+'_roundtest.hpp')).write_text(public)
print('generated ABI candidates')

