#include SIRKIT_LC2D_SOURCE
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <random>
#include <string>
#include <vector>
using ld=long double;
struct Direction { ld a,b; };
struct Summary { ld value=0,x=0,y=0; };
static void barrier() { std::atomic_signal_fence(std::memory_order_seq_cst); }
static std::uint64_t checks=0;
static void require(bool ok) { ++checks;if(!ok)std::abort(); }
static void prepare(const std::string& shape,LineContainer2D& hull,std::vector<Direction>& queries) {
    std::mt19937_64 rng(912783);
    const int n=shape=="one"?1:shape=="small"?32:8192;
    for(int i=0;i<n;++i) {
        if(shape=="lens") {
            const std::int64_t x=i<=4096?i-2048:i-4097-2047;
            const std::int64_t y=i<=4096?x*x:INT64_C(2)*2048*2048-x*x;
            hull.add(x,y);
        } else {
            const ld x=(std::int64_t(rng()%2000001)-1000000)/ld{8};
            const ld y=(std::int64_t(rng()%2000001)-1000000)/ld{16};
            hull.add(x,y);
        }
    }
    queries.resize(250000);
    for(std::size_t i=0;i<queries.size();++i) {
        auto& q=queries[i];q={(std::int64_t(rng()%2000001)-1000000)/ld{16},(std::int64_t(rng()%2000001)-1000000)/ld{131072}};
        if(i%257==0)q.a=0;
        if(i%263==0)q.b=0;
        if(i%1021==0)q={0,0};
    }
}
template<bool Minimum> static void inspect(const LineContainer2D& hull,const std::vector<Direction>& queries) {
    for(const auto q:queries) {
        const auto old_value=Minimum?hull.min_ld(q.a,q.b):hull.max_ld(q.a,q.b);
        const auto old_point=Minimum?hull.argmin(q.a,q.b):hull.argmax(q.a,q.b);
        const auto result=Minimum?hull.min_with_point(q.a,q.b):hull.max_with_point(q.a,q.b);
        require(result.x==old_point.first&&result.y==old_point.second);
        require(result.value==old_value);
        require(result.value==q.a*result.x+q.b*result.y);
    }
}
template<bool Fused,bool Minimum> [[gnu::noinline]] static Summary run(const LineContainer2D& hull,const std::vector<Direction>& queries) {
    Summary out;barrier();
    for(const auto q:queries) {
        if constexpr(Fused) {
            const auto result=Minimum?hull.min_with_point(q.a,q.b):hull.max_with_point(q.a,q.b);
            out.value+=result.value;out.x+=result.x;out.y+=result.y;
        } else {
            const ld value=Minimum?hull.min_ld(q.a,q.b):hull.max_ld(q.a,q.b);
            const auto point=Minimum?hull.argmin(q.a,q.b):hull.argmax(q.a,q.b);
            out.value+=value;out.x+=point.first;out.y+=point.second;
        }
    }
    barrier();return out;
}
template<bool Fused,bool Minimum> static void measure(const char* shape,const char* objective,const LineContainer2D& hull,const std::vector<Direction>& queries) {
    const auto begin=std::chrono::steady_clock::now();const auto result=run<Fused,Minimum>(hull,queries);
    const double ns=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count()/queries.size();
    std::printf("%s:%s %.9f %.18Le,%.18Le,%.18Le\n",shape,objective,ns,result.value,result.x,result.y);
}
int main(int argc,char** argv) {
    const std::string mode=argc>1?argv[1]:"check";
    for(const auto* shape:{"one","small","lens"}) {
        LineContainer2D hull;std::vector<Direction> queries;prepare(shape,hull,queries);
        if(mode=="check") {
            inspect<false>(hull,queries);inspect<true>(hull,queries);
            std::printf("checked %s %zu points min_hull=%zu max_hull=%zu\n",shape,hull.size(),hull.minlc.size(),hull.maxlc.size());
        } else if(mode=="fused") {
            measure<true,false>(shape,"max",hull,queries);measure<true,true>(shape,"min",hull,queries);
        } else {
            measure<false,false>(shape,"max",hull,queries);measure<false,true>(shape,"min",hull,queries);
        }
    }
    if(mode=="check")std::printf("PASS %llu exact result checks\n",static_cast<unsigned long long>(checks));
}

