#include SIRKIT_LC2D_SOURCE
#include <cstdio>
#include <random>
#include <vector>
#include <cstdlib>
#include <cstring>
using ld=long double;
static std::uint64_t checks=0;
static std::int64_t reference(ld value) {
    const ld limited=std::clamp(value,-LineContainer2D::INF,LineContainer2D::INF);
    const std::int64_t integral=static_cast<std::int64_t>(limited);
    const ld fraction=limited-ld(integral);
    return integral+(fraction>=0.5L)-(fraction<=-0.5L);
}
static void inspect(ld value) {
    const auto expected=reference(value);
    const auto actual=LineContainer2D::test_round(value);
    if(expected!=actual || actual!=std::llround(std::clamp(value,-LineContainer2D::INF,LineContainer2D::INF))) {
        std::fprintf(stderr,"mismatch value=%La got=%ld expected=%ld\n",value,actual,expected);std::abort();
    }
    ++checks;
}
static void nearby(ld value) {
    inspect(value);inspect(std::nextafter(value,-std::numeric_limits<ld>::infinity()));inspect(std::nextafter(value,std::numeric_limits<ld>::infinity()));
}
int main() {
    nearby(0);nearby(-0.0L);nearby(0.5L);nearby(-0.5L);nearby(1);nearby(-1);
    nearby(LineContainer2D::INF);nearby(-LineContainer2D::INF);
    inspect(std::numeric_limits<ld>::infinity());inspect(-std::numeric_limits<ld>::infinity());
    inspect(std::numeric_limits<ld>::max());inspect(std::numeric_limits<ld>::lowest());
    inspect(std::numeric_limits<ld>::denorm_min());inspect(-std::numeric_limits<ld>::denorm_min());
    for(int i=-10000;i<=10000;++i) {nearby(ld(i));nearby(ld(i)+0.5L);}
    for(int e=-16400;e<=64;++e) {ld v=std::ldexp(1.0L,e);nearby(v);nearby(-v);}
    for(int e=0;e<=62;++e) {
        const ld center=std::ldexp(1.0L,e);
        for(int i=-64;i<=64;++i) {nearby(center+ld(i)/2);nearby(-center+ld(i)/2);}
    }
    std::mt19937_64 rng(9817283);
    for(int i=0;i<500000;++i) {
        const ld value=static_cast<ld>(static_cast<std::int64_t>(rng()))/std::ldexp(1.0L,int(rng()%130));nearby(value);
    }
#ifndef SIRKIT_LINE_CONTAINER_FORCE_PORTABLE
#if defined(__linux__) && defined(__x86_64__) && (defined(__GNUC__) || defined(__clang__)) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    if constexpr(sizeof(ld)==16 && std::numeric_limits<ld>::digits==64 && std::numeric_limits<ld>::max_exponent==16384 && std::numeric_limits<ld>::radix==2 && std::endian::native==std::endian::little) {
        bool threw=false;try {LineContainer2D::test_round(std::numeric_limits<ld>::quiet_NaN());}catch(const std::overflow_error&) {threw=true;}
        if (!threw) std::abort();
        ++checks;
    }
#endif
#endif
    std::printf("PASS %llu strict rounded boundaries\n",static_cast<unsigned long long>(checks));
}

